package ug.audiocity.studio;
import java.io.*;import java.nio.file.*;
/** Check persisted sample identity against real bundled PCM, including old project migration. */
public final class DrumSampleChoiceTests {
 static int n;static void ok(boolean b,String why){n++;if(!b)throw new AssertionError(why);}static void clean(File f){if(f.isDirectory())for(File c:f.listFiles())clean(c);f.delete();}
 static float[][] kit(File assets,BeatPilotDrumPattern p)throws Exception{float[][] k=new float[8][];for(int l=0;l<8;l++)try(InputStream in=new FileInputStream(new File(assets,"samples/builtin/soundza/"+p.sampleFile(l)))){k[l]=SampleAudio.readWav(in);}return k;}
 public static void main(String[] args)throws Exception{
  File assets=new File(args.length>0?args[0]:"assets");BeatPilotDrumPattern p=new BeatPilotDrumPattern(100,2);for(int l=0;l<8;l++){ok(p.sampleFile(l).equals(BeatPilotDrums.FILES[l]),"factory defaults unchanged");for(int i=0;i<DrumSampleCatalog.FILES[l].length;i++){File f=new File(assets,"samples/builtin/soundza/"+DrumSampleCatalog.FILES[l][i]);ok(f.isFile(),"sample exists: "+f);ok(!DrumSampleCatalog.title(l,i).contains(".wav"),"readable label");}p.setSampleChoice(l,0);p.set(0,l,l,110);}
  BeatPilotDrumPattern round=BeatPilotDrumPattern.decode(p.encode());for(int l=0;l<8;l++){ok(round.sampleChoice(l)==0&&round.get(0,l,l)==110,"selected sound and hits survive encode");ok(p.copy().sampleFile(l).equals(p.sampleFile(l)),"copy keeps kit");ok(p.resized(8).sampleFile(l).equals(p.sampleFile(l)),"resize keeps kit");ok(PatternLibrary.lane(p,l).sampleFile(l).equals(p.sampleFile(l)),"separate lane keeps chosen sample");}
  BeatPilotDrumPattern retimed=BeatPilotDrumPattern.decode(BeatPilotDrumRollData.retempo(p.encode(),140));ok(retimed.bpm==140&&retimed.sampleChoice(0)==0&&retimed.get(0,1,1)==110,"tempo retiming keeps custom samples and hits");
  String old="v2|100|2|"+p.encode().split("\\|",5)[4];BeatPilotDrumPattern migrated=BeatPilotDrumPattern.decode(old);for(int l=0;l<8;l++)ok(migrated.sampleFile(l).equals(BeatPilotDrums.FILES[l])&&migrated.get(0,l,l)==110,"v2 projects keep old sounds");
  for(String bad:new String[]{p.encode().replaceFirst("\\|0,0,0,0,0,0,0,0\\|","|99,0,0,0,0,0,0,0|"),"v4|100|1|../../x|00"}){try{BeatPilotDrumPattern.decode(bad);throw new AssertionError("invalid sample accepted");}catch(IllegalArgumentException expected){n++;}}
  Core.Session s=new Core.Session();File dir=Files.createTempDirectory("acs-sample-choice-").toFile();try{s.directory=dir.getAbsolutePath();PatternLibrary.Entry e=PatternLibrary.add(s,"My sounds",p);PatternLibrary.Entry copy=PatternLibrary.duplicate(s,e.id);s.bpm=120;BeatPilotDrumPattern remap=PatternLibrary.pattern(s,e);ok(remap.bpm==120&&remap.sampleFile(0).equals(p.sampleFile(0)),"tempo changes preserve sample choices");s.bpm=100;float[][] selected=kit(assets,p);java.util.List<Core.Clip> placed=PatternArrangement.place(s,e.id,selected,0,1);Core.Clip kick=placed.get(0);p.setSampleChoice(0,DrumSampleCatalog.defaultIndex(0));PatternArrangement.save(s,e.id,"Changed kick",p,kit(assets,p));Core.Clip changed=s.tracks.get(0).clips.get(0);boolean difference=false;for(int frame=0;frame<10000;frame++)if(Math.abs(kick.source.sample(frame,0)-changed.source.sample(frame,0))>.0001){difference=true;break;}ok(difference,"changing kick updates printed PCM on its own track");ok(s.tracks.size()==8,"eight separate tracks retained");ok(PatternLibrary.pattern(s,copy).sampleChoice(0)==0,"sample edit does not change copied pattern");ProjectIO.save(s);Core.Session loaded=ProjectIO.load(dir,AudioIO.Disk::new);ok(PatternLibrary.pattern(loaded,PatternLibrary.find(loaded,e.id)).sampleFile(0).equals(p.sampleFile(0)),"project reopen keeps selected kick");ok(loaded.tracks.get(0).clips.get(0).drumPattern.startsWith("v4|"),"linked audio retains sample metadata");ok(PatternLibrary.pattern(loaded,PatternLibrary.find(loaded,copy.id)).sampleChoice(1)==0,"other patterns retain own kits");}finally{clean(dir);}
  System.out.println("DrumSampleChoiceTests passed "+n+" checks");
 }
}
